let db,accounts,messages,groups,pushSubscriptions,groupReads,chatRequests,connections,blocks,chatSettings,userSettings,reports,messageDeletes,sessions,notifications,activityLogs;const online=new Map(),rateState=new WeakMap(),serverErrors=[];function logServerError(e,context='runtime'){serverErrors.unshift({context,message:String(e?.message||e),time:Date.now()});if(serverErrors.length>200)serverErrors.pop();console.error(context,e)}
