async function history(kind,key,viewer){
  let rows=messages?await messages.find({kind,chatKey:key,time:{$gt:Date.now()-TTL}},{projection:{_id:0}}).sort({time:1}).toArray():mem.messages.filter(m=>m.kind===kind&&m.chatKey===key&&m.time>Date.now()-TTL).sort((a,b)=>a.time-b.time);
  const lower=String(viewer||'').toLowerCase();
  if(lower){
    if(messageDeletes){const gone=await messageDeletes.find({userLower:lower},{projection:{_id:0,messageId:1}}).toArray();const ids=new Set(gone.map(x=>x.messageId));rows=rows.filter(m=>!ids.has(m.id));}
    else rows=rows.filter(m=>!mem.messageDeletes.has(m.id+'::'+lower));
  }
  return rows;
}
async function createAccount(name,pin){const key=name.toLowerCase(),obj={name,nameLower:key,pinHash:pinHash(pin),bio:'',avatar:'',createdAt:Date.now(),lastSeen:Date.now()};if(accounts){try{await accounts.insertOne(obj);return obj}catch(e){return null}}if(mem.accounts.has(key))return null;mem.accounts.set(key,obj);return obj}
async function findAccount(name){if(accounts)return accounts.findOne({nameLower:name.toLowerCase()});return mem.accounts.get(name.toLowerCase())}
async function findAccounts(names){const keys=[...new Set(names.map(x=>String(x).trim().toLowerCase()).filter(Boolean))];if(accounts)return accounts.find({nameLower:{$in:keys}},{projection:{_id:0,name:1,nameLower:1}}).toArray();return keys.map(k=>mem.accounts.get(k)).filter(Boolean)}
async function groupsFor(name){if(groups)return groups.find({membersLower:name.toLowerCase()},{projection:{_id:0}}).sort({updatedAt:-1}).toArray();return [...mem.groups.values()].filter(g=>g.membersLower.includes(name.toLowerCase())).sort((a,b)=>b.updatedAt-a.updatedAt)}
async function getGroup(id){if(groups)return groups.findOne({id},{projection:{_id:0}});return mem.groups.get(id)}
async function updateGroupName(id,name){if(groups){await groups.updateOne({id},{$set:{name,updatedAt:Date.now()}});return getGroup(id)}const g=mem.groups.get(id);if(g){g.name=name;g.updatedAt=Date.now()}return g}
async function markDirectSeen(withName,viewer){const key=pair(withName,viewer);const now=Date.now();let changed=[];if(messages){const rows=await messages.find({kind:'direct',chatKey:key,to:viewer,status:{$ne:'seen'},time:{$gt:Date.now()-TTL}}).toArray();for(const m of rows){await messages.updateOne({id:m.id},{$set:{status:'seen',seenAt:now}});changed.push(m.id)}}else{for(const m of mem.messages.filter(x=>x.kind==='direct'&&x.chatKey===key&&x.to===viewer&&x.status!=='seen'&&x.time>Date.now()-TTL)){m.status='seen';m.seenAt=now;changed.push(m.id)}}return changed}
async function getUnreadCounts(name){const out={direct:{},group:{}};const key=name.toLowerCase();let deleted=new Set();if(messageDeletes){const gone=await messageDeletes.find({userLower:key},{projection:{_id:0,messageId:1}}).toArray();deleted=new Set(gone.map(x=>x.messageId))}else deleted=new Set([...mem.messageDeletes].filter(x=>x.endsWith('::'+key)).map(x=>x.split('::')[0]));if(messages){const direct=await messages.find({kind:'direct',to:name,status:{$ne:'seen'},time:{$gt:Date.now()-TTL}},{projection:{from:1,id:1}}).toArray();for(const m of direct){if(deleted.has(m.id))continue;const k=unreadKeyServer('direct',m.from);out.direct[k]=(out.direct[k]||0)+1}const gs=await groupsFor(name);for(const g of gs){let since=0;if(groupReads){const r=await groupReads.findOne({nameLower:key,groupId:g.id});since=Number(r?.lastSeenAt||0)}const rows=await messages.find({kind:'group',chatKey:g.id,from:{$ne:name},system:{$ne:true},time:{$gt:Math.max(since,Date.now()-TTL)}},{projection:{id:1}}).toArray();const n=rows.filter(m=>!deleted.has(m.id)).length;if(n)out.group[g.id]=n}}else{for(const m of mem.messages){if(m.time<=Date.now()-TTL||m.system||deleted.has(m.id))continue;if(m.kind==='direct'&&m.to===name&&m.status!=='seen'){const k=unreadKeyServer('direct',m.from);out.direct[k]=(out.direct[k]||0)+1}}for(const g of await groupsFor(name)){const n=mem.messages.filter(m=>m.kind==='group'&&m.chatKey===g.id&&!m.system&&m.from!==name&&m.time>Date.now()-TTL&&!deleted.has(m.id)).length;if(n)out.group[g.id]=n}}return out}
function unreadKeyServer(type,id){return `${type}:${String(id).toLowerCase()}`}
async function emitUnreadToUser(name){if(!name)return;const data=await getUnreadCounts(name);for(const sock of io.sockets.sockets.values())if(sock.data.userName?.toLowerCase()===name.toLowerCase())sock.emit('unreadCounts',data)}
async function markGroupSeen(groupId,viewer){if(!groupId||!viewer)return;const now=Date.now();if(groupReads)await groupReads.updateOne({nameLower:viewer.toLowerCase(),groupId:String(groupId)},{$set:{nameLower:viewer.toLowerCase(),groupId:String(groupId),lastSeenAt:now,updatedAt:now}},{upsert:true});await emitUnreadToUser(viewer)}
async function save(m){if(!m.expiresAt)m.expiresAt=new Date(m.time+TTL);if(messages)await messages.insertOne(m);else mem.messages.push(m)}
async function saveGroupEvent(groupId,text){const m={id:'sys-'+Date.now()+'-'+Math.random().toString(36).slice(2),kind:'group',chatKey:groupId,groupId,system:true,text,time:Date.now(),status:'sent'};await save(m);return m}
