function markOnline(s){const n=s.data.userName,key=s.data.nameLower;if(!n||!key)return;online.set(key,{name:n,socketId:s.id});s.data.awake=true;s.data.visible=true}
async function setLastSeen(key){const now=Date.now();if(accounts)await accounts.updateOne({nameLower:key},{$set:{lastSeen:now}});else{const a=mem.accounts.get(key);if(a)a.lastSeen=now}}
async function markOfflineIdentity(name,key,socketId){if(!name||!key)return;const x=online.get(key);if(x&&x.socketId===socketId)online.delete(key);await setLastSeen(key);await emitPeople()}
async function markOffline(s){const n=s.data.userName,key=s.data.nameLower;if(!n||!key)return;await markOfflineIdentity(n,key,s.id)}
function connectionKey(a,b){return pair(a,b)}
async function isBlocked(a,b){const key=pair(a,b);if(blocks)return !!(await blocks.findOne({key}));return mem.blocks.has(key)}
async function getConnections(name){const key=name.toLowerCase();let out=[];if(connections){const rows=await connections.find({$or:[{aLower:key},{bLower:key}]},{projection:{_id:0,a:1,b:1,aLower:1,bLower:1}}).toArray();out.push(...rows.map(r=>r.aLower===key?r.b:r.a).filter(Boolean));if(messages){const old=await messages.find({kind:'direct',$or:[{from:name},{to:name}]},{projection:{from:1,to:1}}).limit(500).toArray();for(const m of old)out.push(m.from?.toLowerCase()===key?m.to:m.from)}}else{for(const k of mem.connections){const [a,b]=k.split('::');if(a===key)out.push(b);else if(b===key)out.push(a)}for(const m of mem.messages.filter(x=>x.kind==='direct')){if(m.from?.toLowerCase()===key)out.push(m.to);else if(m.to?.toLowerCase()===key)out.push(m.from)}}return [...new Set(out.map(x=>String(x).toLowerCase()))]}
async function directRelationship(a,b){if(!a||!b||a.toLowerCase()===b.toLowerCase())return 'none';if(await isBlocked(a,b))return 'blocked';const connected=(await getConnections(a)).includes(b.toLowerCase());if(connected)return 'connected';if(messages){const old=await messages.findOne({kind:'direct',chatKey:pair(a,b)},{projection:{_id:1}});if(old)return 'connected'}else if(mem.messages.some(m=>m.kind==='direct'&&m.chatKey===pair(a,b)))return 'connected';return 'none'}
async function expireRequests(){const cutoff=Date.now()-7*24*60*60*1000;if(chatRequests)await chatRequests.updateMany({status:'pending',createdAt:{$lt:cutoff}},{$set:{status:'expired',respondedAt:Date.now()}});else mem.chatRequests.forEach(r=>{if(r.status==='pending'&&r.createdAt<cutoff){r.status='expired';r.respondedAt=Date.now()}})}
async function getChatRequests(name){await expireRequests();const key=name.toLowerCase();if(chatRequests){return {incoming:await chatRequests.find({toLower:key,status:'pending'},{projection:{_id:0}}).sort({createdAt:-1}).toArray(),outgoing:await chatRequests.find({fromLower:key,status:'pending'},{projection:{_id:0}}).sort({createdAt:-1}).toArray()}}return {incoming:mem.chatRequests.filter(r=>r.toLower===key&&r.status==='pending'),outgoing:mem.chatRequests.filter(r=>r.fromLower===key&&r.status==='pending')}}
async function emitChatRequests(name){const req=await getChatRequests(name);for(const sock of io.sockets.sockets.values())if(sock.data.userName?.toLowerCase()===name.toLowerCase())sock.emit('chatRequests',req)}
async function saveConnection(a,b){const al=a.toLowerCase(),bl=b.toLowerCase(),key=pair(a,b);if(connections)await connections.updateOne({key},{$set:{key,a:a,nameA:a,b:b,nameB:b,aLower:al,bLower:bl,createdAt:Date.now()}},{upsert:true});else mem.connections.add(key)}
async function removeConnection(a,b){const key=pair(a,b);if(connections)await connections.deleteOne({key});else mem.connections.delete(key)}
function groupAdmins(g){return Array.isArray(g?.admins)&&g.admins.length?g.admins:[g?.createdBy].filter(Boolean)}
function isGroupAdmin(g,name){return groupAdmins(g).some(x=>String(x).toLowerCase()===String(name).toLowerCase())}
function isMainGroupAdmin(g,name){return !!g&&String(g.createdBy).toLowerCase()===String(name).toLowerCase()}

async function getUserSettings(name){const key=String(name||'').toLowerCase();if(!key)return {ownerLower:key,privacy:{online:true,lastSeen:true,profilePhoto:true,readReceipts:true,requests:'everyone'},theme:'system',compact:false,accent:'#2563eb',bubble:'default',notifications:{sound:true,browser:true,badge:true,messages:true,requests:true,groups:true,mentions:true,replies:true},joinedDateVisible:true};if(userSettings)return await userSettings.findOne({ownerLower:key},{projection:{_id:0}})||{ownerLower:key,privacy:{online:true,lastSeen:true,profilePhoto:true,readReceipts:true,requests:'everyone'},theme:'system',compact:false,accent:'#2563eb',bubble:'default',notifications:{sound:true,browser:true,badge:true,messages:true,requests:true,groups:true,mentions:true,replies:true},joinedDateVisible:true};return mem.userSettings.get(key)||{ownerLower:key,privacy:{online:true,lastSeen:true,profilePhoto:true,readReceipts:true,requests:'everyone'},theme:'system',compact:false,accent:'#2563eb',bubble:'default',notifications:{sound:true,browser:true,badge:true,messages:true,requests:true,groups:true,mentions:true,replies:true},joinedDateVisible:true}}
