function tokenHash(t){return crypto.createHash('sha256').update(String(t)).digest('hex')}
async function createSession(name,sock,meta={}){const token=crypto.randomBytes(32).toString('hex'),now=Date.now(),doc={tokenHash:tokenHash(token),userLower:name.toLowerCase(),name,createdAt:now,lastUsedAt:now,expiresAt:new Date(now+180*24*60*60*1000),device:meta.device||'Browser',userAgent:meta.userAgent||'',ip:meta.ip||'',socketId:sock?.id||null};if(sessions)await sessions.insertOne(doc);return token}
async function getSession(token){if(!token||!sessions)return null;return sessions.findOne({tokenHash:tokenHash(token),expiresAt:{$gt:new Date()}},{projection:{_id:0}})}
async function touchSession(token,sock){if(!token||!sessions)return;await sessions.updateOne({tokenHash:tokenHash(token)},{$set:{lastUsedAt:Date.now(),socketId:sock?.id||null}})}
async function deleteSession(token){if(sessions&&token)await sessions.deleteOne({tokenHash:tokenHash(token)})}
async function deleteAllSessions(name,except){if(!sessions)return;const q={userLower:name.toLowerCase()};if(except)q.tokenHash={$ne:tokenHash(except)};await sessions.deleteMany(q)}
async function logActivity(action,user,target='',meta={}){if(activityLogs)await activityLogs.insertOne({action,user,target,meta,createdAt:Date.now()})}
async function saveNotification(name,kind,title,body,data={}){if(!notifications)return;await notifications.insertOne({userLower:name.toLowerCase(),kind,title,body,data,createdAt:Date.now(),expiresAt:new Date(Date.now()+30*24*60*60*1000),read:false})}

