 s.on('joinGroupInvite',async(p,ack)=>{const token=String(p?.token||''),me=s.data.userName;if(!token||!me){ack?.({ok:false,error:'Invalid invite.'});return}const g=groups?await groups.findOne({inviteToken:token},{projection:{_id:0}}):[...mem.groups.values()].find(x=>x.inviteToken===token);if(!g){ack?.({ok:false,error:'Invite not found or expired.'});return}if(g.membersLower.includes(me.toLowerCase())){ack?.({ok:true,group:g,already:true});return}if(g.joinApproval){g.pendingMembers=[...new Set([...(g.pendingMembers||[]),me])];if(groups)await groups.updateOne({id:g.id},{$set:{pendingMembers:g.pendingMembers,updatedAt:Date.now()}});else mem.groups.set(g.id,g);for(const admin of groupAdmins(g))await saveNotification(admin,'groupJoinRequest','Group join request',`${me} requested to join ${g.name}`,{groupId:g.id,user:me});ack?.({ok:true,pending:true,group:g});return}g.members.push(me);g.membersLower.push(me.toLowerCase());g.updatedAt=Date.now();if(groups)await groups.updateOne({id:g.id},{$set:{members:g.members,membersLower:g.membersLower,updatedAt:g.updatedAt}});else mem.groups.set(g.id,g);ack?.({ok:true,group:g});});

