function adminOk(req){const secret=process.env.ADMIN_SECRET;return !!secret&&String(req.headers['x-admin-secret']||req.query.secret||'')===secret}
app.get('/api/admin/metrics',async(req,res)=>{if(!adminOk(req))return res.status(401).json({error:'Unauthorized'});try{const now=Date.now(),day=24*60*60*1000;const total=accounts?await accounts.countDocuments({}):mem.accounts.size;const active=accounts?await accounts.countDocuments({lastSeen:{$gt:now-7*day}}):total;const onlineCount=online.size;const registrations=accounts?await accounts.countDocuments({createdAt:{$gt:now-day}}):0;const pending=chatRequests?await chatRequests.countDocuments({status:'pending'}):mem.chatRequests.filter(x=>x.status==='pending').length;const conv=messages?await messages.distinct('chatKey',{kind:'direct',time:{$gt:now-TTL}}):[];const groupCount=groups?await groups.countDocuments({}):mem.groups.size;const reportsCount=reports?await reports.countDocuments({status:'open'}):mem.reports.filter(x=>x.status==='open').length;const blocked=blocks?await blocks.countDocuments({}):mem.blocks.size;const dbStats=db?await db.stats():{};return res.json({totalUsers:total,activeUsers:active,onlineUsers:onlineCount,newRegistrations:registrations,pendingRequests:pending,activeConversations:conv.length,groups:groupCount,reportedUsers:reportsCount,blockedAccounts:blocked,storageUsageBytes:dbStats.storageSize||0,database:dbStats})}catch(e){res.status(500).json({error:e.message})}})
app.get('/api/admin/users',async(req,res)=>{if(!adminOk(req))return res.status(401).json({error:'Unauthorized'});const rows=accounts?await accounts.find({},{projection:{_id:0,name:1,nameLower:1,createdAt:1,lastSeen:1,suspended:1}}).sort({createdAt:-1}).limit(500).toArray():[...mem.accounts.values()];res.json({users:rows.map(x=>({...x,online:online.has(x.nameLower)}))})})
app.post('/api/admin/user-action',async(req,res)=>{if(!adminOk(req))return res.status(401).json({error:'Unauthorized'});const name=String(req.body?.name||'').trim(),action=String(req.body?.action||'');if(!name)return res.status(400).json({error:'Name required'});const a=await findAccount(name);if(!a)return res.status(404).json({error:'User not found'});if(action==='suspend'||action==='restore'){if(accounts)await accounts.updateOne({nameLower:a.nameLower},{$set:{suspended:action==='suspend',updatedAt:Date.now()}});if(action==='suspend'&&sessions)await sessions.deleteMany({userLower:a.nameLower});return res.json({ok:true})}if(action==='delete'){if(accounts)await accounts.deleteOne({nameLower:a.nameLower});if(sessions)await sessions.deleteMany({userLower:a.nameLower});if(connections)await connections.deleteMany({$or:[{aLower:a.nameLower},{bLower:a.nameLower}]});if(chatRequests)await chatRequests.deleteMany({$or:[{fromLower:a.nameLower},{toLower:a.nameLower}]});if(messages)await messages.deleteMany({$or:[{from:a.name},{to:a.name}]});return res.json({ok:true})}return res.status(400).json({error:'Unknown action'})})
app.get('/api/admin/reports',async(req,res)=>{if(!adminOk(req))return res.status(401).json({error:'Unauthorized'});const rows=reports?await reports.find({}).sort({createdAt:-1}).limit(200).toArray():mem.reports;res.json({reports:rows})})
app.get('/api/admin/activity',async(req,res)=>{if(!adminOk(req))return res.status(401).json({error:'Unauthorized'});const rows=activityLogs?await activityLogs.find({}).sort({createdAt:-1}).limit(300).toArray():[];res.json({activity:rows})})
app.get('/api/admin/errors',async(req,res)=>{if(!adminOk(req))return res.status(401).json({error:'Unauthorized'});res.json({errors:serverErrors,note:'These are errors captured by the FiveChat process since the current server start. Render logs remain the source for full historical stack traces.'})})

app.post('/api/ai/suggest',async(req,res)=>{const key=process.env.OPENAI_API_KEY;const text=String(req.body?.text||'').trim().slice(0,2000);if(!text)return res.status(400).json({error:'Text required'});if(!key){const fallback=text.replace(/\b(i|im|i'm)\b/gi,'I').replace(/\s+/g,' ').trim();return res.json({suggestions:[fallback,`Could you please clarify: ${fallback}`,`Thanks for the message. ${fallback}`],mode:'local'});}try{const r=await fetch('https://api.openai.com/v1/responses',{method:'POST',headers:{'Content-Type':'application/json','Authorization':`Bearer ${key}`},body:JSON.stringify({model:process.env.OPENAI_MODEL||'gpt-5-mini',input:`Give 3 concise reply suggestions for this chat message. Return only a JSON array of strings. Message: ${text}`})});const data=await r.json();const out=data.output_text||'';let suggestions=[];try{suggestions=JSON.parse(out)}catch{suggestions=out.split('\n').map(x=>x.replace(/^[-*\d.]+\s*/,'').trim()).filter(Boolean).slice(0,3)}res.json({suggestions,mode:'ai'});}catch(e){res.status(502).json({error:'AI service unavailable'})}});

